class Probe:
    def __init__(self,args=None,env=None):
        self.p=subprocess.Popen(['/workspace/executable']+(args or []),stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=env)
    def send(self,obj):
        data=json.dumps(obj,separators=(',',':')).encode()
        self.p.stdin.write(b'Content-Length: '+str(len(data)).encode()+b'\r\n\r\n'+data); self.p.stdin.flush()
    def raw(self,data):
        self.p.stdin.write(data); self.p.stdin.flush()
    def read(self,wait=.25):
        outs=[b'',b'']; end=time.monotonic()+wait
        while time.monotonic()<end:
            avail,_,_=select.select([self.p.stdout,self.p.stderr],[],[],max(0,end-time.monotonic()))
            if not avail: break
            for f in avail:
                x=os.read(f.fileno(),65536)
                if x: outs[0 if f is self.p.stdout else 1]+=x
            if self.p.poll() is not None: break
        for n,x in zip(['OUT','ERR'],outs):
            if x: print(n,repr(x.decode(errors='replace')),flush=True)
        return outs
    def done(self):
        self.p.stdin.close();self.read(.5)
        if self.p.poll() is None:self.p.terminate()
        self.p.wait(); print('EXIT',self.p.returncode,flush=True)
