    def __init__(self, code=0):
        self.code = code

def similarity(a, b):
    """Jaro-Winkler similarity, used for typo hints."""
    if a == b: return 1.0
    if not a or not b: return 0.0
    radius = max(len(a), len(b)) // 2 - 1
    radius = max(radius, 0)
    aa, bb = [False]*len(a), [False]*len(b)
    count = 0
    for i, c in enumerate(a):
        for j in range(max(0, i-radius), min(len(b), i+radius+1)):
            if not bb[j] and c == b[j]:
                aa[i] = bb[j] = True
                count += 1
                break
    if count == 0: return 0.0
    av = [x for i,x in enumerate(a) if aa[i]]
    bv = [x for i,x in enumerate(b) if bb[i]]
    trans = sum(x != y for x,y in zip(av,bv))/2
    score = (count/len(a) + count/len(b) + (count-trans)/count)/3
    if score > .7:
        prefix = 0
        for x,y in zip(a[:4],b[:4]):
            if x != y: break
            prefix += 1
        score += prefix*.1*(1-score)
    return score

def suggestions(word, choices):
    rated = [(similarity(word, x), n, x) for n, x in enumerate(choices)]
    return [x for score,n,x in sorted(rated) if score > .7]

class Parser:
    def __init__(self, argv):
        self.argv = argv
        self.name = os.path.basename(sys.argv[0]) or 'executable'
        self.context = ''
        self.flags = {}
        self.path = None
        self.shell = None

    def error(self, message, tips='', use=None):
        out = 'error: ' + message + '\n'
        if tips: out += '\n' + tips + '\n'
        if use is not False:
            out += '\nUsage: ' + (use or usage(self.context, self.name)) + '\n'
        out += "\nFor more information, try '--help'.\n"
        sys.stderr.write(out)
        raise Done(2)

    def subcommand_error(self, value):
        hints = suggestions(value, CHILDREN.get(self.context, []))
        tip = ''
        if len(hints) == 1:
            tip = f"  tip: a similar subcommand exists: '{hints[0]}'"
        elif hints:
            tip = '  tip: some similar subcommands exist: ' + ', '.join("'"+x+"'" for x in hints)
