                self.context = c
                self.subcommand_error(a)
            c = (c+' '+a).strip()
        self.context = c
        self.help()

    def setflag(self, key, value=True):
        if key in self.flags and key != 'quiet':
            label = '--' + key
            if key == 'path': label += ' <path>'
            self.error(f"the argument '{label}' cannot be used multiple times")
        if key == 'quiet': value = min(255, self.flags.get(key,0)+1)
        self.flags[key] = value

    def parse(self):
        i = 0
        stop = False
        while i < len(self.argv):
            a = self.argv[i]
            i += 1
            if not stop and a == '--':
                stop = True
                continue
            allowed = {x[0] for x in OPTIONS.get(self.context, [])} | {'help'}
            shorts = {x[1]:x[0] for x in OPTIONS.get(self.context, []) if x[1]}
            shorts['h'] = 'help'
            if not stop and a.startswith('--'):
                key, eq, value = a[2:].partition('=')
                if key not in allowed:
                    self.unexpected(a)
                label = '--'+key + ('...' if key == 'quiet' else '')
                if key == 'path':
                    if not eq:
                        if i < len(self.argv) and not self.argv[i].startswith('-'):
                            value = self.argv[i]
                            i += 1
                    if not value:
                        self.error("a value is required for '--path <path>' but none was supplied", use=False)
