                        elif self.context == 'completions': u += ' <SHELL>'
                        self.error(f"unexpected value '{value}' for '{label}' found; no more were expected", use=u)
                    if key == 'help': self.help()
                    self.setflag(key)
                continue
            if not stop and a.startswith('-') and len(a)>1:
                for short in a[1:]:
                    if short not in shorts:
                        self.unexpected('-'+short)
                    key = shorts[short]
                    if key == 'help': self.help(False)
                    self.setflag(key)
                continue
            if self.context in CHILDREN:
                if stop: self.unexpected(a, True)
                if a not in CHILDREN[self.context]: self.subcommand_error(a)
                if a == 'help': self.help_command(self.argv[i:])
                self.context = (self.context+' '+a).strip()
            elif self.context == 'check' and self.path is None:
                self.path = a
            elif self.context == 'completions' and self.shell is None:
                self.shell = a
            else:
                self.unexpected(a)
        if self.context == 'completions':
            if self.shell is None:
                self.error('the following required arguments were not provided:\n  <SHELL>')
            if self.shell not in SHELLS:
                msg = f"invalid value '{self.shell}' for '<SHELL>'\n  [possible values: " + ', '.join(SHELLS) + ']'
                hints = suggestions(self.shell, SHELLS)
                tip = f"  tip: a similar value exists: '{hints[-1]}'" if hints else ''
                self.error(msg, tip, False)
        return self

