    try:
        p = Parser(argv).parse()
        if p.context == '':
            if p.flags.get('version'):
                print(('' if p.flags.get('quiet') else 'RustOwl ') + VERSION)
                return 0
            from server import Server
            return Server().run()
        if p.context == 'completions':
            from completions import render
            sys.stdout.write(render(p.shell))
            return 0
        from runtime import commands
        return commands(p.context, p.path, p.flags)
    except Done as e:
        return e.code
