    'help': 'Print this message or the help of the given subcommand(s)',
}
SHELLS = ['bash', 'elvish', 'fish', 'powershell', 'zsh', 'nushell']
SHELL_DESCRIPTIONS = ['Bourne Again `SHell` (bash)', 'Elvish shell',
                      'Friendly Interactive `SHell` (fish)', '`PowerShell`',
                      'Z `SHell` (zsh)', 'Nushell']
# (long option, short option, argument, description)
OPTIONS = {
    '': [('version', 'V', '', 'Print version'),
         ('quiet', 'q', '', 'Suppress output'),
         ('stdio', '', '', 'Use stdio to communicate with the LSP server')],
    'check': [('all-targets', '', '', 'Run the check for all targets instead of current only'),
              ('all-features', '', '', 'Run the check for all features instead of the current active ones only')],
    'toolchain install': [('path', '', 'path', 'Runtime directory path to install RustOwl toolchain'),
                          ('skip-rustowl-toolchain', '', '', 'Install Rust toolchain only')],
}
CHILDREN = {'': ['check', 'clean', 'toolchain', 'completions', 'help'],
            'toolchain': ['install', 'uninstall', 'help']}
HELP_DESC = DESCRIPTIONS['help']

def options(command):
    return OPTIONS.get(command, []) + [('help', 'h', '', 'Print help' + (" (see more with '--help')" if command == 'completions' else ''))]

def description(command):
    if command in DESCRIPTIONS:
        return DESCRIPTIONS[command]
    if command.endswith('help'):
        return HELP_DESC
    return DESCRIPTIONS.get(command.replace('help ', ''), '')

def usage(command, name='executable'):
    suffix = {'': '[OPTIONS] [COMMAND]', 'check': '[OPTIONS] [path]',
              'clean': '', 'toolchain': '[COMMAND]',
              'toolchain install': '[OPTIONS]', 'toolchain uninstall': '',
              'completions': '<SHELL>', 'help': '[COMMAND]...',
              'toolchain help': '[COMMAND]...'}[command]
    return ' '.join(x for x in (name, command, suffix) if x)

def help_text(command='', name='executable', long=True):
    if command == '':
        return f'''Usage: {usage(command, name)}

Commands:
  check        Check availability
  clean        Remove artifacts from the target directory
  toolchain    Install or uninstall the toolchain
  completions  Generate shell completions
  help         Print this message or the help of the given subcommand(s)

Options:
  -V, --version   Print version
  -q, --quiet...  Suppress output
      --stdio     Use stdio to communicate with the LSP server
  -h, --help      Print help
'''
    header = description(command) + '\n\nUsage: ' + usage(command, name) + '\n\n'
    if command == 'check':
        return header + '''Arguments:
  [path]  The path of a file or directory to check availability

Options:
      --all-targets   Run the check for all targets instead of current only
      --all-features  Run the check for all features instead of the current active ones only
  -h, --help          Print help
'''
    if command in ('clean', 'toolchain uninstall'):
        return header + 'Options:\n  -h, --help  Print help\n'
    if command == 'toolchain':
        return header + '''Commands:
  install    Install the toolchain
  uninstall  Uninstall the toolchain
  help       Print this message or the help of the given subcommand(s)

Options:
  -h, --help  Print help
'''
    if command == 'toolchain install':
        return header + '''Options:
      --path <path>             Runtime directory path to install RustOwl toolchain
      --skip-rustowl-toolchain  Install Rust toolchain only
  -h, --help                    Print help
'''
    if command == 'completions':
        if not long:
            return header + "Arguments:\n  <SHELL>  The shell to generate completions for [possible values: " + ', '.join(SHELLS) + "]\n\nOptions:\n  -h, --help  Print help (see more with '--help')\n"
        return header + '''Arguments:
  <SHELL>
          The shell to generate completions for

          Possible values:
          - bash:       Bourne Again `SHell` (bash)
          - elvish:     Elvish shell
          - fish:       Friendly Interactive `SHell` (fish)
          - powershell: `PowerShell`
          - zsh:        Z `SHell` (zsh)
          - nushell:    Nushell

Options:
  -h, --help
          Print help (see a summary with '-h')
'''
    return header + 'Arguments:\n  [COMMAND]...  Print help for the subcommand(s)\n'
