"""Streaming, stateful JSON-RPC endpoint for the ownership visualizer."""
import heapq
import json
import os
import re
import select
import sys
import time
import uuid
from interface import VERSION
from protocol import (MISSING, ParamError, REQUESTS, NOTIFICATIONS, dump,
                      file_path, url_path)
from runtime import Logger, ensure_runtime, valid_target

CAPABILITIES = {
    'capabilities': {
        'textDocumentSync': {'change':2,'openClose':True,'save':True},
        'workspace': {'workspaceFolders':{'changeNotifications':True,'supported':True}}
    }
}
ERRORS = {-32700:'Parse error',-32600:'Invalid request',-32601:'Method not found',
          -32602:'Invalid params',-32002:'Server not initialized',-32800:'Canceled'}

def sorted_value(v):
    if isinstance(v,dict): return {k:sorted_value(v[k]) for k in sorted(v)}
    if isinstance(v,list): return [sorted_value(x) for x in v]
    return v

def error_response(id,code,message=None,data=MISSING):
    err={'code':code,'message':message if message is not None else ERRORS[code]}
    if data is not MISSING: err['data']=data
    return {'jsonrpc':'2.0','error':err,'id':id}

def result_response(id,result):
    return {'jsonrpc':'2.0','result':sorted_value(result),'id':id}

class FrameError(Exception): pass

class Framer:
    def __init__(self):
        self.buffer=b''
        self.length=None
    def add(self, data): self.buffer+=data
    def take(self, eof=False):
        frames=[]
        while True:
            if self.length is None:
                m=re.search(b'\r?\n\r?\n',self.buffer)
                if not m:
                    if eof and self.buffer: raise FrameError()
                    break
                header=self.buffer[:m.start()]
                self.buffer=self.buffer[m.end():]
                length=None
                for line in header.splitlines():
                    if b':' not in line: raise FrameError()
                    key,value=line.split(b':',1)
                    value=value.strip()
                    if key==b'Content-Length':
                        if not re.fullmatch(b'\+?[0-9]+',value): raise FrameError()
                        length=int(value)
                        if length>2**63-1: raise FrameError()
                    if key==b'Content-Type':
                        if not re.search(br'charset\s*=\s*(utf-8|utf8)\s*$',value,re.I):
                            raise FrameError()
                if length is None: raise FrameError()
                self.length=length
            if len(self.buffer)<self.length:
                if eof: raise FrameError()
                break
            data=self.buffer[:self.length]
            self.buffer=self.buffer[self.length:]
            self.length=None
            if data: frames.append(data)
            if not self.buffer: break
        return frames

class Server:
    def __init__(self):
        self.state='new'
        self.log=Logger()
        self.initial=None
        self.out=[]
        self.exit_code=0
        self.progress=False
        self.documents={}
        self.targets=[]
        self.analyzing=False
        self.progress_requests={}
        self.next_request=0
        self.tasks=[]
        self.task_counter=0
        self.blocked=[]
        self.framer=Framer()
        self.stop=False

    def emit(self,obj): self.out.append(obj)
    def error(self,id,code,message=None,data=MISSING): self.emit(error_response(id,code,message,data))
    def result(self,id,value): self.emit(result_response(id,value))
    def flush(self):
        for obj in self.out:
            data=dump(obj).encode('utf-8')
            sys.stdout.buffer.write(b'Content-Length: '+str(len(data)).encode()+b'\r\n\r\n'+data)
        if self.out: sys.stdout.buffer.flush()
        self.out=[]
    def later(self,delay,fn):
        self.task_counter+=1
        heapq.heappush(self.tasks,(time.monotonic()+delay,self.task_counter,fn))
    def run_tasks(self,force=False):
        now=time.monotonic()
        while self.tasks and (force or self.tasks[0][0]<=now):
            _,_,fn=heapq.heappop(self.tasks)
